s=s.replace("new List<string>()","new List<Failure>()")
s=s.replace('else if (run.Dispenser.Dispenses.Count > 0) failures.Add($"{label} : Dispense appelé pendant un dépôt");',
 'else if (run.Dispenser.Dispenses.Count > 0) failures.Add(new("Dispense appelé pendant un dépôt", label));')
open(p,'w').write(s)
EOF
